use serde_json::{json,Value};use std::{fs,path::{Path,PathBuf},collections::BTreeMap,process::Command};use sha2::{Sha256,Digest};
const R:&str="/home/ubuntu/src/zopro-perf-work/control-codegen175";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){let r=Path::new(R);assert!(!r.join("text-differences.json").exists());let a=read(r.join("analysis.json"));let variants=&a["variants"];let mut data=BTreeMap::new();let mut funcs=BTreeMap::new();for v in["accepted","combined_OFF"]{let cell=&variants[v];let bytes=fs::read(cell["binary"].as_str().unwrap()).unwrap();assert_eq!(format!("{:x}",Sha256::digest(&bytes)),cell["ELF_sha256"]);let offset=cell["text_offset"].as_u64().unwrap()as usize;let len=cell["text_bytes"].as_u64().unwrap()as usize;let section=fs::read_to_string(r.join(format!("{v}-sections.txt"))).unwrap();let line=section.lines().find(|l|l.split_whitespace().any(|w|w==".text")).unwrap();let f=line.split_whitespace().collect::<Vec<_>>();let idx=f.iter().position(|&w|w==".text").unwrap();let base=u64::from_str_radix(f[idx+2],16).unwrap();data.insert(v,(bytes[offset..offset+len].to_vec(),base));let raw=read(r.join(format!("{v}-demangled.json")));let mut ranges=Vec::new();for(raw,cell)in raw.as_object().unwrap(){let start=u64::from_str_radix(cell["address_hex"].as_str().unwrap(),16).unwrap();ranges.push((start,start+cell["size"].as_u64().unwrap(),raw.clone(),cell["name"].as_str().unwrap().to_string()));}ranges.sort();funcs.insert(v,ranges);}
let (av,base)=&data["accepted"];let (bv,bb)=&data["combined_OFF"];assert_eq!(base,bb);assert_eq!(av.len(),bv.len());let mut changed=BTreeMap::<String,Value>::new();let mut bytes_changed=0;let mut outside=Vec::new();for(i,(&aa,&bb))in av.iter().zip(bv).enumerate(){if aa==bb{continue}bytes_changed+=1;let addr=base+i as u64;let owners=funcs["accepted"].iter().filter(|f|f.0<=addr&&addr<f.1).collect::<Vec<_>>();if owners.is_empty(){outside.push(format!("{addr:x}"));}for f in owners{let entry=changed.entry(f.2.clone()).or_insert_with(||json!({"name":f.3,"start_hex":format!("{:x}",f.0),"length":f.1-f.0,"byte_differences":[]}));entry["byte_differences"].as_array_mut().unwrap().push(json!({"offset":addr-f.0,"accepted":aa,"OFF":bb}));}}
let mut mismatched_addresses=Vec::new();for af in &funcs["accepted"]{let matching=funcs["combined_OFF"].iter().filter(|bf|bf.2==af.2).collect::<Vec<_>>();if matching.len()!=1||matching[0].0!=af.0||matching[0].1!=af.1{mismatched_addresses.push(json!({"symbol":af.2,"accepted_start":af.0,"accepted_end":af.1,"OFF_matches":matching}));}}
let mut assembly=BTreeMap::new();for(raw,cell)in &changed{let mut files=BTreeMap::new();for v in["accepted","combined_OFF"]{let binary=variants[v]["binary"].as_str().unwrap();let o=Command::new("objdump").args(["-d","--no-show-raw-insn"]).arg(format!("--disassemble={raw}")).arg(binary).output().unwrap();assert!(o.status.success());let filename=format!("{v}-{:x}.asm",Sha256::digest(raw.as_bytes()));let path=r.join(&filename);fs::write(&path,&o.stdout).unwrap();files.insert(v,filename);}assembly.insert(raw,json!({"name":cell["name"],"files":files}));}
let result=json!({"text_bytes":av.len(),"different_text_bytes":bytes_changed,"changed_function_symbols":changed,"differences_outside_function_ranges":outside,"raw_symbol_address_mismatches":mismatched_addresses,"assembly":assembly,"static_only":true,"new_SDK_requests":0,"new_proofs":0});fs::write(r.join("text-differences.json"),serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("Different textbytes{bytes_changed};changedfunctionsymbols{};outside{};rawsymboladdressmismatch{}",changed.len(),result["differences_outside_function_ranges"].as_array().unwrap().len(),result["raw_symbol_address_mismatches"].as_array().unwrap().len());for (_,cell)in &changed{println!("{} changedbytes{}",cell["name"].as_str().unwrap(),cell["byte_differences"].as_array().unwrap().len());}
}
